//! The public game SDK: bindings of every public `rescaleframe/*.h` contract header outside the
//! games and integrations (generated by build.rs), plus the helpers integrations share.

#[allow(
    non_camel_case_types,
    non_upper_case_globals,
    non_snake_case,
    dead_code,
    clippy::all
)]
mod sys {
    include!(concat!(env!("OUT_DIR"), "/sys.rs"));
}
pub use sys::*;

